/// <summary>
/// CB201_RebatesExtension_GSTchanges
/// Intialize rebate transaction gets the source item sales tax group
/// </summary>
/// <param name = "_rebateTrans">TAMRebateTrans buffer</param>
/// <param name = "_rebateJournalTrans">TAMRebateJournalTrans buffer</param>
/// <param name = "_rebateDatePeriod">RebateDatePeriod given as part fo rebate transaction</param>
/// <returns>true or false</returns>
protected boolean inititalizeRebateTransaction(TAMRebateTrans _rebateTrans, TAMRebateJournalTrans _rebateJournalTrans, TAMRebateDatePeriod _rebateDatePeriod)
{
    boolean ret = next inititalizeRebateTransaction(_rebateTrans, _rebateJournalTrans, _rebateDatePeriod);

    // Bug 293935: CB705  - Item GST group is not copied from Source transaction
    // Moved temporary fix in a separate method
    this.setRebateTransAdditionalFields(_rebateTrans, _rebateJournalTrans, _rebateDatePeriod);        

    return ret;
}

/// <summary>
/// Bug 293935: CB705  - Item GST group is not copied from Source transaction
/// Permanent fix, extensibility requests not required in the end
/// </summary>
/// <param name = "_rebateTrans">TAMRebateTrans buffer</param>
/// <param name = "_rebateJournalTrans">TAMRebateJournalTrans buffer</param>
/// <param name = "_rebateDatePeriod">RebateDatePeriod given as part fo rebate transaction</param>
protected void setRebateTransAdditionalFields(TAMRebateTrans _rebateTrans, TAMRebateJournalTrans _rebateJournalTrans, TAMRebateDatePeriod _rebateDatePeriod)
{
    METItemType itemType;
    boolean followTransItemGSTGroup = this.getTAMRebatePostingProfile().METFollowTransItemGSTGroup;

    if (followTransItemGSTGroup)
    {
        _rebateTrans.METTaxItemGroup = _rebateJournalTrans.metGetTaxItemGroup();
    }

    if (rebateParameters.METProcessByCustRebateInvByItemType)
    {
        itemType = METItemType::find(InventTable::metGetItemType(_rebateTrans.ItemId, InventDim::find(_rebateTrans.InventDimId).InventSiteId));
        _rebateTrans.METItemTypes = itemType.ItemType;
        _rebateTrans.METItemTypeDescription = itemType.Description;                
    }        
}

/// <summary>
/// Task182820-CB272_SalesInvoicing-rebates
/// Get Rebate posting profile
/// </summary>
/// <returns>TAMRebatePosting</returns>
public TAMRebatePosting getTAMRebatePostingProfile()
{
    return this.processByDeal ?
        TAMRebatePosting::find(rebateDeal.RebatePostingId, rebateDeal.ModuleInventCustVend) :
        TAMRebatePosting::find(rebateTable.RebatePostingId, rebateTable.ModuleInventCustVend);
}

/// <summary>
/// CB705_VendorRebatePosting init the TAMRebateDateTrans vendor rebate type id
/// </summary>
/// <param name = "_rebateDateTrans"><c>TAMRebateDateTrans</c> record</param>
protected void initRebateDateTrans(TAMRebateDateTrans _rebateDateTrans)
{
    next initRebateDateTrans(_rebateDateTrans);

    if (rebateParameters.METProcessVendRebateBasedVendRebType
    &&  rebateTransactionType == TAMRebateTransactionType::Rebate
    &&  rebateDeal.METInvoiceConsolidationByRebateType)
    {
        _rebateDateTrans.METVendRebateTypeId = rebateTable.METVendRebateTypeId;
    }
}

/// <summary>
/// CB705_VendorRebatePosting
/// To make sure RemittanceAccount, ModuleInventCustVend and RefCompanyId are set using the new rebatePosting.DynamicAccount == TAMRebateDynamicAccount::METPurchasedFromVendor
/// </summary>
/// <param name = "_rebateDateTrans"><c>TAMRebateDateTrans</c> record</param>
protected void updateRemittanceAccount(TAMRebateDateTrans _rebateDateTrans)
{
    next updateRemittanceAccount(_rebateDateTrans);

    if (rebateParameters.METProcessVendRebateBasedVendRebType
    &&  this.rebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        // Retrieve rebatePosting record
        TAMRebatePosting rebatePosting = this.getRebatePostingProfile();

        if (rebatePosting.RebatePostingType == TAMRebatePostingAccountType::CustVend
        &&  rebatePosting.DynamicAccount    == TAMRebateDynamicAccount::METPurchasedFromVendor)
        {
            // Set the RemittanceAccount from the line custom vendor account field instead (copied from the deal header)
            _rebateDateTrans.RemittanceAccount = rebateTable.METVendAccount;

            this.updateDateTransModuleAndRefCompanyId(_rebateDateTrans, this.getDateTransModuleDynamicAccountIsNone(rebatePosting), rebatePosting.RebateCompany);
        }         
    }
}

/// <summary>
/// Bug 290034: CB201- For volumetric rebate Process>Rebate transaction, Source transaction is not looking at the Rebate management number of Tier Line type Value
/// Exclude the rebate line with Rate tier line type from Process > provision and rebate management so it does not create
/// any rebate date transactions and rebate source transactions
/// </summary>
/// <param name = "_rebateDatePeriod"><c>TAMRebateDatePeriod</c></TAMRebateDatePeriod></param>
/// <returns>True to create the TAMRebateTrans; otherwise, false.</returns>
protected boolean checkIfToCreateRebateDateTransactions(TAMRebateDatePeriod _rebateDatePeriod)
{
    boolean ret = next checkIfToCreateRebateDateTransactions(_rebateDatePeriod);

    if (rebateDeal.METVolumetricTierDeal
    &&  rebateTable.METTierLineType == METTierLineType::Rate)
    {
        // to skip creation of rebate transactions provision and rebate management for the volumetric rate line
        ret = false;
    }

    return ret;
}

/// <summary>
/// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
/// </summary>
/// <param name = "_rebateTransId">Rebate transaction id</param>
/// <param name = "_rebateAmount">Rebate amount</param>
protected void createRebateDateTrans(TAMRebateTransId _rebateTransId, TAMRebateDeductionAmount _rebateAmount)
{
    // After rebateTrans and rebateDateTrans are created
    next createRebateDateTrans(_rebateTransId, _rebateAmount);

    // Update external sales data provision or rebate processed to Yes
    METRebateScanSupplierTable::updateProcessedFlags(rebateTransactionType, NoYes::Yes, _rebateTransId);        
}

